{
  "implementation": "def solve(case):
    payload = case['payload']
    word_token_indices = payload['word_token_indices']
    word_scores = payload['word_scores']
    forced_words = payload['forced_words']
    token_budget = payload['token_budget']

    n_words = len(word_token_indices)
    if len(word_scores) != n_words:
        raise ValueError("Mismatched lengths")

    forced_set = set(forced_words)
    forced_tokens = 0
    for i in forced_set:
        if i < 0 or i >= n_words:
            raise ValueError("Invalid forced word index")
        forced_tokens += len(word_token_indices[i])

    if forced_tokens > token_budget:
        return {"error": "infeasible forced set"}

    remaining_budget = token_budget - forced_tokens
    selected = set(forced_set)

    candidates = []
    for i in range(n_words):
        if i not in forced_set:
            candidates.append((-word_scores[i], i, len(word_token_indices[i])))
    candidates.sort()

    for score_neg, i, cnt in candidates:
        if remaining_budget >= cnt:
            selected.add(i)
            remaining_budget -= cnt
        if remaining_budget == 0:
            break

    result_tokens = []
    for i in range(n_words):
        if i in selected:
            result_tokens.extend(word_token_indices[i])
    return result_tokens
